using namespace scratcher;
namespace {
int checks=0;
void check(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
template<class Callback>void rejects(Callback callback,const char* message){bool rejected=false;try{callback();}catch(const std::exception&){rejected=true;}check(rejected,message);}
Json call(Engine& engine,const char* name,Json args=Json::object()){auto result=callRecognitionTool(engine,name,args);if(!result)throw std::runtime_error("Missing recognition dispatch");return *result;}
void write(const std::filesystem::path& path,const std::string& bytes){std::ofstream file(path,std::ios::binary);file.write(bytes.data(),static_cast<std::streamsize>(bytes.size()));}
Json signature(const char* id,const char* name,const char* pattern){return {{"id",id},{"name",name},{"library","owned-test-library"},{"architecture","x86_64"},{"pattern",pattern},{"source","Test fixture"}};}
}
