 call(engine,"add_library_signature",signature("alias","other_fn","55 48 89 E5 E8 ?? ?? ?? ?? 90 90 C3"));matched=call(engine,"identify_libraries");check(matched["matches"][0]["ambiguous"]==true&&matched["matches"][0]["candidates"].size()==2,"Colliding identities report ambiguity");
