 rejects([&]{call(engine,"add_library_signature",signature("masked","duplicate","55 48 89 E5"));},"Duplicate ids rejected");rejects([&]{call(engine,"add_library_signature",signature("weak","too_weak","55 ?? ?? ??"));},"Low fixed-bit signatures rejected");rejects([&]{call(engine,"add_library_signature",signature("bad","bad_pattern","55 48 89 ZZ"));},"Malformed pattern rejected");
