 std::atomic_bool flag=true;engine.setCancellation(&flag);matched=call(engine,"identify_libraries");check(matched["cancelled"]==true&&matched["functions_examined"]==0,"Recognition cancellation returns honest progress");rejects([&]{call(engine,"add_library_signature",signature("cancelled","cancelled","55 48 89 E5"));},"Cancelled mutation rejected");engine.setCancellation(nullptr);
